class Solution {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        int n = nums.size();
        set<vector<int>> uniq;
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j < n; ++j)
                for (int k = j + 1; k < n; ++k)
                    for (int l = k + 1; l < n; ++l) {
                        long long s = (long long)nums[i] + nums[j] + nums[k] + nums[l];
                        if (s == target) {
                            vector<int> q = {nums[i], nums[j], nums[k], nums[l]};
                            sort(q.begin(), q.end());
                            uniq.insert(q);
                        }
                    }
        return vector<vector<int>>(uniq.begin(), uniq.end());
    }
};

